#!/usr/bin/env node
/**
 * Points impeccable (the design skill in .claude/skills/impeccable) at the Design OS context, so
 * both read the same truth. impeccable looks for PRODUCT.md and DESIGN.md in the project root,
 * then in `.agents/context/`; two symlinks there lead to the Design OS files:
 *
 *   .agents/context/DESIGN.md  -> product/design-system/DESIGN.md   (generated by npm run tokens:build)
 *   .agents/context/PRODUCT.md -> wiki/product/PRODUCT.md            (compiled by /design-os:wiki-ingest --product)
 *
 * It also records `buildPath: "code"` in `.impeccable/config.json`: prototypes are built in code,
 * never from generated image comps. Idempotent; a missing target leaves its link out.
 *
 *   npm run impeccable:context            what is linked and what is missing
 *   npm run -s impeccable:context -- --json
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

export const CONTEXT_DIR = '.agents/context'
export const LINKS = [
  { name: 'DESIGN.md', target: 'product/design-system/DESIGN.md', fix: 'npm run tokens:build' },
  { name: 'PRODUCT.md', target: 'wiki/product/PRODUCT.md', fix: '/design-os:wiki-ingest --product' },
]
const CONFIG = '.impeccable/config.json'

/** Creates the links and the config; returns what each link is now */
export function linkContext(root) {
  const dir = path.join(root, CONTEXT_DIR)
  const links = LINKS.map(({ name, target, fix }) => {
    const link = path.join(dir, name)
    const relative = path.relative(dir, path.join(root, target))
    let current = null
    try {
      current = fs.readlinkSync(link)
    } catch {
      // No link yet (or a plain file, which is left alone below)
    }
    if (!fs.existsSync(path.join(root, target))) {
      if (current !== null) fs.unlinkSync(link)
      return { name, target, status: 'missing', fix }
    }
    if (current === relative) return { name, target, status: 'linked' }
    if (current === null && fs.existsSync(link)) return { name, target, status: 'blocked', fix: `remove ${CONTEXT_DIR}/${name}, Design OS owns it` }
    fs.mkdirSync(dir, { recursive: true })
    if (current !== null) fs.unlinkSync(link)
    fs.symlinkSync(relative, link)
    return { name, target, status: 'linked' }
  })

  const configPath = path.join(root, CONFIG)
  let config = {}
  try {
    config = JSON.parse(fs.readFileSync(configPath, 'utf8'))
  } catch {
    // Missing or unreadable: start from the Design OS defaults
  }
  if (config.buildPath !== 'code') {
    fs.mkdirSync(path.dirname(configPath), { recursive: true })
    fs.writeFileSync(configPath, `${JSON.stringify({ ...config, buildPath: 'code' }, null, 2)}\n`)
  }
  return { links, config: CONFIG }
}

/** Vite plugin: links the context when the dev server starts, so the chat agent finds it */
export function impeccableContext() {
  return {
    name: 'designos-impeccable-context',
    apply: 'serve',
    configResolved(config) {
      try {
        linkContext(config.root)
      } catch (error) {
        config.logger.warn(`impeccable context: ${error.message}`)
      }
    },
  }
}

function main() {
  const result = linkContext(process.cwd())
  if (process.argv.includes('--json')) {
    console.log(JSON.stringify(result, null, 2))
    return
  }
  for (const l of result.links) {
    const line = l.status === 'linked' ? `${CONTEXT_DIR}/${l.name} -> ${l.target}` : `${CONTEXT_DIR}/${l.name}: ${l.status} (${l.target}) — ${l.fix}`
    console.log(line)
  }
  console.log(`${result.config}: buildPath code`)
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main()
